CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL DEFAULT 'My workspace', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_org ON public.organizations FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY own_org_update ON public.organizations FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'Organization Admin' CHECK(role IN ('Super Admin','Organization Admin','Manager','Sales Executive','Support Executive','Viewer')), UNIQUE(user_id,organization_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.crm_org() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT organization_id FROM public.user_roles WHERE user_id=auth.uid() LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.crm_org() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.crm_org() TO authenticated;
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), company text NOT NULL DEFAULT '' CHECK(length(company)<=100), email text NOT NULL DEFAULT '' CHECK(length(email)<=255), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), value numeric(14,2) NOT NULL DEFAULT 0 CHECK(value>=0), status text NOT NULL DEFAULT 'New Inquiry' CHECK(status IN ('New Inquiry','Requirement Gathering','Proposal Sent','Design Approved','Development In Progress','Testing','Ready for Delivery','Delivered','Post-Launch Support','Lead On Hold','Lost')), label text NOT NULL DEFAULT 'Warm' CHECK(label IN ('Hot','Warm','Cold')), source text NOT NULL DEFAULT 'Direct' CHECK(length(source)<=100), contacted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_leads ON public.leads FOR ALL TO authenticated USING(organization_id=public.crm_org() AND owner_id=auth.uid()) WITH CHECK(organization_id=public.crm_org() AND owner_id=auth.uid());
CREATE TABLE public.activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), lead_id uuid NOT NULL REFERENCES public.leads(id) ON DELETE CASCADE, type text NOT NULL CHECK(type IN ('Call','Meeting','Follow-up','Site visit','WhatsApp','Email','Demo','Feedback','Other','Note')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=4000), occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.activities TO authenticated; GRANT ALL ON public.activities TO service_role;
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_activities ON public.activities FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org() AND EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id AND owner_id=auth.uid()));
CREATE TABLE public.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), lead_id uuid REFERENCES public.leads(id) ON DELETE SET NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), due_at timestamptz NOT NULL, priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('High','Medium','Low')), completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tasks ON public.tasks FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org() AND (lead_id IS NULL OR EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id AND owner_id=auth.uid())));
CREATE TABLE public.content_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), body text NOT NULL DEFAULT '' CHECK(length(body)<=20000), category text NOT NULL DEFAULT 'General' CHECK(length(category)<=100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.content_pages TO authenticated; GRANT ALL ON public.content_pages TO service_role;
ALTER TABLE public.content_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_content ON public.content_pages FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org());
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), sku text NOT NULL DEFAULT '' CHECK(length(sku)<=100), price numeric(14,2) NOT NULL DEFAULT 0 CHECK(price>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_products ON public.products FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org());
CREATE FUNCTION public.crm_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); INSERT INTO public.organizations(owner_id) VALUES(NEW.id) RETURNING id INTO org; INSERT INTO public.user_roles(user_id,organization_id,role) VALUES(NEW.id,org,'Organization Admin'); RETURN NEW; END $$;
CREATE TRIGGER crm_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.crm_signup();
CREATE INDEX leads_owner ON public.leads(owner_id,created_at); CREATE INDEX activities_lead ON public.activities(lead_id); CREATE INDEX tasks_owner_due ON public.tasks(owner_id,due_at);